"""
Birth location
--------------
Resolves a place of birth to coordinates and a UTC offset, or fails loudly.

There is deliberately no fallback to a default city: computing a chart with
someone else's coordinates produces a confidently wrong Lagna, which is worse
than refusing to compute at all.

Where the IANA time-zone database is available (zoneinfo, standard library)
the UTC offset is resolved for the actual birth moment, so historical rules
and daylight saving are handled. Otherwise the fixed offset recorded in the
city table is used and the result says so.
"""

# Generated by GitHub Copilot - Sep-27-2026

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass
from typing import Optional

try:
    from zoneinfo import ZoneInfo, ZoneInfoNotFoundError
    _HAS_TZDATA = True
except ImportError:                                  # pragma: no cover
    ZoneInfo = None                                  # type: ignore
    ZoneInfoNotFoundError = Exception                # type: ignore
    _HAS_TZDATA = False


class LocationError(ValueError):
    """Raised when a birth place cannot be resolved to valid coordinates."""


@dataclass(frozen=True)
class BirthLocation:
    """A fully resolved place of birth. Every field is known, none is guessed."""

    name: str
    latitude: float
    longitude: float
    timezone_name: str
    utc_offset_at_birth: float          # hours east of Greenwich
    source: str                         # how this was resolved

    def __post_init__(self):
        if not -90.0 <= self.latitude <= 90.0:
            raise LocationError(
                f"Latitude {self.latitude} is outside -90..90")
        if not -180.0 <= self.longitude <= 180.0:
            raise LocationError(
                f"Longitude {self.longitude} is outside -180..180")
        if not -12.0 <= self.utc_offset_at_birth <= 14.0:
            raise LocationError(
                f"UTC offset {self.utc_offset_at_birth} is outside -12..+14")

    def to_utc(self, local: datetime.datetime) -> datetime.datetime:
        return local - datetime.timedelta(hours=self.utc_offset_at_birth)

    def offset_text(self) -> str:
        sign = "+" if self.utc_offset_at_birth >= 0 else "-"
        total = abs(self.utc_offset_at_birth)
        hours, minutes = int(total), round((total - int(total)) * 60)
        return f"UTC{sign}{hours:02d}:{minutes:02d}"

    def describe(self) -> str:
        return (f"{self.name}  ({self.latitude:.4f}°, {self.longitude:.4f}°, "
                f"{self.timezone_name} {self.offset_text()})")


