def _normalise(text: str) -> str:
    text = text.strip().lower()
    text = re.sub(r"[,\.].*$", "", text)             # drop ", Rajasthan, India"
    text = re.sub(r"[^a-z\s]", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def known_cities() -> list[str]:
    return sorted(CITY_TABLE)


# ── Coordinate parsing ────────────────────────────────────────────────────────

_COORD_RE = re.compile(
    r"^\s*(?P<deg>-?\d+(?:\.\d+)?)\s*(?:[°d:]\s*)?"
    r"(?:(?P<min>\d+(?:\.\d+)?)\s*(?:['m:]\s*)?)?"
    r"(?:(?P<sec>\d+(?:\.\d+)?)\s*[\"s]?\s*)?"
    r"(?P<hemi>[NSEWnsew])?\s*$")


def parse_coordinate(text: str, kind: str) -> float:
    """Parse '26.9124', '26 54 45 N' or '75°47\\'14\"E' into signed degrees."""
    if isinstance(text, (int, float)):
        return float(text)
    match = _COORD_RE.match(str(text))
    if not match:
        raise LocationError(f"Cannot read {kind} from '{text}'")
    value = (float(match.group("deg"))
             + float(match.group("min") or 0) / 60
             + float(match.group("sec") or 0) / 3600)
    hemisphere = (match.group("hemi") or "").upper()
    if hemisphere in ("S", "W"):
        value = -abs(value)
    return value


def parse_utc_offset(text) -> float:
    """Parse '+05:30', '5.5', '-8' into hours east of Greenwich."""
    if isinstance(text, (int, float)):
        return float(text)
    raw = str(text).strip().upper().replace("UTC", "").replace("GMT", "").strip()
    if not raw:
        raise LocationError("Empty UTC offset")
    match = re.match(r"^([+-]?)(\d{1,2})(?::?(\d{2}))?$", raw)
    if match:
        sign = -1.0 if match.group(1) == "-" else 1.0
        hours = int(match.group(2))
        minutes = int(match.group(3) or 0)
        return sign * (hours + minutes / 60.0)
    try:
        return float(raw)
    except ValueError as exc:
        raise LocationError(f"Cannot read UTC offset from '{text}'") from exc


# ── Resolution ────────────────────────────────────────────────────────────────

def offset_from_timezone(timezone_name: str,
                         local: datetime.datetime) -> Optional[float]:
    """UTC offset of an IANA zone at a local moment, or None if unavailable."""
    if not _HAS_TZDATA:
        return None
    try:
        zone = ZoneInfo(timezone_name)
    except (ZoneInfoNotFoundError, ValueError, KeyError):
        return None
    offset = local.replace(tzinfo=zone).utcoffset()
    return None if offset is None else offset.total_seconds() / 3600.0


def lookup_city(place: str) -> Optional[tuple[str, tuple]]:
    """Find a city by exact or unambiguous prefix match. Never guesses."""
    key = _normalise(place)
    if not key:
        return None
    if key in CITY_TABLE:
        return key, CITY_TABLE[key]
    prefixed = [name for name in CITY_TABLE if name.startswith(key)]
    if len(prefixed) == 1:
        return prefixed[0], CITY_TABLE[prefixed[0]]
    return None


def resolve_location(place: Optional[str] = None,
                     latitude=None,
                     longitude=None,
                     timezone: Optional[str] = None,
                     utc_offset=None,
                     local_datetime: Optional[datetime.datetime] = None
                     ) -> BirthLocation:
    """
    Resolve a birth place. Explicit coordinates always win over the city table.
    Raises LocationError rather than substituting a different city.
    """
    has_coordinates = latitude is not None and longitude is not None
    if (latitude is None) != (longitude is None):
        raise LocationError(
            "Latitude and longitude must be given together")

    entry = lookup_city(place) if place else None
    moment = local_datetime or datetime.datetime(2000, 1, 1, 12, 0)

    if has_coordinates:
        lat = parse_coordinate(latitude, "latitude")
        lon = parse_coordinate(longitude, "longitude")
        zone_name = timezone or (entry[1][2] if entry else None)
        source = "explicit coordinates"
    elif entry:
        name, (lat, lon, city_zone, _) = entry
        zone_name = timezone or city_zone
        source = f"city table entry '{name}'"
    else:
        raise LocationError(
            f"Birth place '{place}' is not in the city database.\n"
            f"    Supply coordinates explicitly, for example:\n"
            f"      --place \"{place}\" --lat 26.9124 --lon 75.7873 "
            f"--timezone Asia/Kolkata\n"
            f"    or --utc-offset +05:30 if the zone name is unknown.\n"
            f"    Known cities: {', '.join(known_cities()[:8])}, …"
            f" ({len(CITY_TABLE)} total)")

    if utc_offset is not None:
        offset = parse_utc_offset(utc_offset)
        zone_label = zone_name or f"fixed {offset:+g}h"
        source += ", explicit UTC offset"
    elif zone_name:
        resolved = offset_from_timezone(zone_name, moment)
        if resolved is None:
            if entry:
                offset = entry[1][3]
                zone_label = f"{zone_name} (fixed offset, no tz database)"
                source += ", fixed offset fallback"
            else:
                raise LocationError(
                    f"Time zone '{zone_name}' could not be resolved and no "
                    f"--utc-offset was supplied")
        else:
            offset = resolved
            zone_label = zone_name
            source += ", IANA time zone"
    else:
        raise LocationError(
            "No time zone or UTC offset supplied for these coordinates. "
            "Pass --timezone or --utc-offset.")

    return BirthLocation(
        name=place or f"{lat:.4f},{lon:.4f}",
        latitude=lat,
        longitude=lon,
        timezone_name=zone_label,
        utc_offset_at_birth=offset,
        source=source,
    )
